(7482437, 1190039, 30861, '<td valign="top">Having fun with your drone, mate? Be hard to follow up your brilliant blue...</td>', 'Having fun with your drone, mate? Be hard to follow up your brilliant blue...', '2016-11-14 00:09:20.000000', NULL, 1),
