(7482458, 1190540, 61396, '<td valign="top">this jumps at me. it is hard not to see this in 3D.</td>', 'this jumps at me. it is hard not to see this in 3D.', '2016-11-14 01:42:38.000000', NULL, 1),
(7482498, 1190522, 114285, '<td valign="top">Looks like the winner so far, excellent POV. Could of won the "from above " challenge</td>', 'Looks like the winner so far, excellent POV. Could of won the "from above " challenge', '2016-11-14 09:11:02.000000', NULL, 1),
